"""Serialize authored institutional memory design, not legal-power inference."""
import json
import re
from pathlib import Path
RUN=Path(__file__).resolve().parent
def refs(*ns): return [f'SRC-{n:03d}' for n in ns]

def build():
    rows=[
      ('Core Public Organisation Vocabulary','European Union SEMIC','https://semiceu.github.io/CPOV/releases/2.1.1/','2.1.1 Recommendation 2024-05-06','standard','Selected institution, identifier, territory, framework and change concepts; sector extensions remain separate.'),
      ('The Organization Ontology','W3C','https://www.w3.org/TR/vocab-org/','Recommendation; exact dated pin and update audit pending','ontology','Selected posts, memberships, sites and change events; reporting is not universal delegation.'),
      ('Core Public Service Vocabulary Application Profile','European Union SEMIC','https://semiceu.github.io/CPSV-AP/releases/3.2.0/','3.2.0 Recommendation 2024-05-06','standard','Selected competent-authority versus delivery-provider relation; no full legal-power inference.'),
      ('Public bodies','UK Cabinet Office','https://www.gov.uk/guidance/public-bodies-reform','Updated 2025-01-07','public-authority','UK administrative categories and distinct economic classification; not a global definition.'),
      ('Statistical classification to the public sector','Office for National Statistics','https://www.ons.gov.uk/economy/governmentpublicsectorandtaxes/publicsectorfinance/methodologies/statisticalclassificationtothepublicsector','Revised 2024-07-08','public-authority','Selected control and independence distinctions; no mechanical ownership or funding test.'),
      ('Publication schemes: a guide','Information Commissioner Office','https://ico.org.uk/for-organisations/foi/publication-schemes-a-guide/','Guidance inspected 2026-09-09','public-authority','Selected publication-guide and exception principles; no blanket disclosure authority.')]
    sources=[dict(id=f'SRC-{i:03d}',title=t,organization=o,url=u,version_or_date=v,source_type=k,primary_source=True,authority_tier=1,accessed_at='2026-09-09T23:17:00Z',relevance=r) for i,(t,o,u,v,k,r) in enumerate(rows,1)]
    ids=['institution-identity','institution-boundary','institution-foundation','institution-competence','institution-organs','institution-oversight','institution-services','institution-channels','institution-transparency','institution-custody','institution-succession','institution-mapping']
    citations=[refs(1,2,4),refs(1,4,5),refs(1,4),refs(1,2,3,4),refs(1,2),refs(2,4,5),refs(1,3),refs(1,2),refs(4,6),refs(1,6),refs(1,2,4),refs(1,2,3,6)]
    kinds=[['identity','evidence','classification'],['relationship','classification','quality'],['provenance','authority','lifecycle'],['constraint','authority','evidence'],['composition','relationship','exception'],['relationship','ownership','classification'],['definition','authority','composition'],['spatial','spatial','validation'],['evidence','access','process'],['provenance','quality','retention'],['event','temporal','relationship'],['interoperability','constraint','validation']]
    bundles=[]; n=0
    for group in re.split(r'(?m)^## ',(RUN/'question-design.md').read_text(encoding='utf-8'))[1:]:
        title=re.sub(r'^\d+\s+','',group.split('\n',1)[0]); layers=[]
        for section in re.split(r'(?m)^### ',group)[1:]:
            heading,body=section.split('\n',1); name=re.sub(r'^\d+\.\d+\s+','',heading)
            qs,answers=body.split('Answer groups:',1); questions=re.findall(r'(?m)^\d\. (.+\?)$',qs); groups=re.findall(r'([a-zA-Z]+)\{([^}]+)\}',answers)
            assert len(questions)==len(groups)==3
            lid=ids[n]; sr=citations[n]; desc='Authored institutional-record design for '+name.lower()+'. Selected sources motivate distinctions; legal interpretations and operational enforcement require separate profiles.'
            fields=[dict(id=lid+'-'+key.lower(),name=key,description='Proposed members: '+members+'. The required container may express unknown or not-applicable; executable nested schemas are deferred.',value_kind='object',cardinality='1',required=True,source_refs=sr) for key,members in groups]
            finding=dict(id=lid+'-record',name=name+' record',description=desc,source_refs=sr,questions=[dict(id=lid+f'-q{i+1:02d}',text=q,kind=kinds[n][i],answer_data=[fields[i]['id']]) for i,q in enumerate(questions)],data_elements=fields,artifacts=[dict(id=lid+'-artifact',name=name+' evidence record',description='Minimal attributed institutional record or authorized source reference, not a fabricated legal instrument or unrestricted copy of internal files.',media_or_form=['text/markdown','application/json','application/yaml','authorized reference'],serial=True,identity_strategy='Master-qualified institution identifier, governed URI or Dimension UUID with separate record revision and digest; never name or timestamp alone.',source_refs=sr)],inline_only_rationale=None)
            layers.append(dict(id=lid,name=name,description=desc,source_refs=sr,findings=[finding])); n+=1
        bundles.append(dict(id='public-'+re.sub('[^a-z]+','-',title.lower()).strip('-'),name=title,description='Public institution '+title.lower()+'.',rationale='Groups institution-owned context without mastering sovereign state, service, postholder or legislation lifecycles.',source_refs=sorted(set(s for l in layers for s in l['source_refs'])),layers=layers))
    assert len(bundles)==6 and n==12
    model=dict(registry_id='vr.wm-pol-016',model_id='WM-POL-016',name='Public Authority / Institution',entry_kind='entity',purpose='Describe a public institution and its source-qualified legal competence, institutional structure and accountability context.',scope_statement='One public institution, potentially lacking separate legal personality, with evidenced identity, basis, competence, relationships and institutional changes. Classification is not proof of powers.',in_scope=['Institution identity, classifications, legal basis and bounded competence assertions','Organs, oversight, service responsibility and public contact references','Transparency, evidence custody, succession and loss-aware mappings'],out_of_scope=['A sovereign state, individual officeholder, building or full service catalogue','Legal advice, automatic power inference, policy enforcement or government decision execution','Private personnel, case files and complete financial or statutory instrument masters'],boundary_notes=[dict(neighbor=a,distinction=b,source_refs=s) for a,b,s in [('Organization','Public institutional specialization is conceptual; registry parent WM-ORG-001 is not a ratified inherited schema.',refs(1,2)),('Public service','Responsible institution and delivery provider differ; service details stay referenced.',refs(1,3)),('Post and officeholder','Institution persists through vacancies; a post and its current holder have distinct records.',refs(2)),('Statistical sector','Statistical public control does not decide independence or legal competence.',refs(4,5)),('Site','Address or office presence is not institutional identity or jurisdiction.',refs(1,2))]])
    services=dict(
      dimension=dict(owner_package_requirements=['Declare institution-record steward distinct from the institution and its legal authorities.','Register official institution, instrument, service and evidence masters.','Bind attribution, interpretation, access, disclosure, correction and retention policies.'],namespace_guidance='Use qualified institution identifiers and independent instrument/post/service references; preserve source jurisdiction and revision.',registry_links=['Institution registry','Instrument and mandate references','Organization/post and service registries','Evidence, succession and policy references']),
      canon_and_patch=dict(canonicalization_rules=['Preserve classifications with their schemes and authority; never infer powers from a category.','Keep institutional effective time, evidence observation and local recording time distinct.'],patch_rules=['Pin base version/digest; namespace jurisdiction and institution-type extensions.','Append source-qualified corrections under expected-head checks; unresolved competing authority remains visible.'],compatibility_rules=['Renaming is not automatically a successor institution.','Reject projection losing required competence, time, identity or disclosure qualifiers.']),
      artifact_rules=dict(identity_priority=['Master-system qualified institution identifier','Governed global institution URI','Dimension-issued UUID'],timestamp_rule='Use RFC 3339 seconds and explicit offset or Z for recording instants; preserve date-only and uncertain legal effect separately.',serial_naming_rule='Opaque institution ID plus record kind and revision; no restricted personnel or case details in names.',integrity_rule='Verify exact-byte digest and source revision; integrity is not legal authority or authentic institutional mandate.'),
      policies=['Local memory edits do not create, abolish or change an institution or legal competence.','Do not infer public power from a website, funding, classification, service delivery or reporting line.','Public information access does not grant universal redistribution or authority to act.','Preserve unknown personality, disputed competence and missing information without fabrication.'],
      crud=dict(read=['Read Dimension authority, pinned specification, assurance holds and evidence access policy before institution records.'],create=['Record source-qualified institutional assertions within delegated local scope; do not invent legal facts.'],update=['Append changes with instrument/source references, effective time, reason and expected-head guard.'],delete=['Apply authorized retention and legal-hold policy to local copies; retain only permitted minimal tombstones. Deletion does not abolish an institution or erase public obligations.']),
      roles=[dict(name=a,responsibilities=[b]) for a,b in [('Dimension owner','Delegates local memory scope, not government powers.'),('Institution steward','Maintains attributed identity and mandate references.'),('Contributor','Supplies authorized source references and uncertainty.'),('Reviewer','Checks boundary, profile and interpretation limits.'),('Custodian','Enforces access, disclosure and retention policies.')]],
      access=dict(default_rule='Deny absent scope-specific authority; public institutional identity does not make every linked record public.',scopes=['bundle','layer','finding','artifact'],exceptions=['Explicit scoped time-limited exception with authorizer and rationale; never implied by a government label.'],audit_requirements=['Record operation, opaque object/revision and authorized outcome without secrets or restricted source contents.']),
      agents_bootstrap=dict(filename='AGENTS.md',required_fields=['Name','Type','Specification URL','Storage type URL','Interface URL','Processes URL'],read_order=['Dimension scope and institutional evidence policy','Pinned specification and assurance limits','Identity, legal basis and qualified competence','Authorized record operations, projection checks and retirement']))
    frows=[('resolve-institution','Resolve institution reference',['Qualified ID','Official evidence'],['Reference or ambiguity'],['Read authority','No name-only merge'],['Read-only; no identity mastering'],refs(1,2)),('record-institution-basis','Record institutional basis',['Instrument references','Effective period','Expected head'],['Attributed basis revision'],['Write authority','Source limits explicit'],['No legal institution created or amended'],refs(1,4)),('link-service-responsibility','Link service responsibility',['Service reference','Authority and provider evidence'],['Qualified responsibility link'],['Authorized sources','Delivery and competence distinct'],['No outsourcing or responsibility transfer performed'],refs(1,3)),('record-institution-change','Record institutional change',['Change evidence','Predecessor/successor refs','Expected head'],['Change assertion or contested set'],['Identity continuity reviewed','Effective date preserved'],['No real merger, abolition or custody transfer'],refs(1,2,4)),('record-publication-policy','Record publication scope',['Authorized policy','Record-class refs','Exceptions'],['Disclosure policy reference'],['Policy authority verified','No private content needed'],['No publication or access expansion by this function'],refs(6)),('export-institution-projection','Export allowed projection',['Disclosure scope','Pinned mapping profile','Loss policy'],['Projection or refusal'],['Export authorized','Required qualifiers preserved'],['No implied legal conformance or public release'],refs(1,2,3,6))]
    functions=[dict(id=i,name=n,description='Proposed local record operation: '+n.lower()+'. Execution adapter is not implemented.',inputs=a,outputs=b,preconditions=c,effects=e,source_refs=s) for i,n,a,b,c,e,s in frows]
    composition=[dict(target=t,relation=r,purpose=p,required=False,source_refs=s) for t,r,p,s in [('WM-ORG-001','ALIGN','Candidate general organization alignment, not ratified inheritance.',refs(1,2)),(rows[0][2],'ALIGN','Institution fields with sector-specific limits.',refs(1)),(rows[1][2],'ALIGN','Posts, sites and changes, without legal-power entailment.',refs(2)),(rows[2][2],'ALIGN','Referenced service responsibility, not a full service model.',refs(3))]]
    dims=[('identity','Institution distinct from names, sites and holders.'),('classification','Administrative and statistical schemes separated.'),('direct properties','Legal personality, level, basis and scope explicitly qualified.'),('recognition','Official evidence and identity ambiguity, not website inference.'),('capabilities','Record operations distinct from real legal powers.'),('lifecycle','Foundation, reorganization, succession and local retirement.'),('relationships','Posts, oversight, services and instruments referenced.'),('temporal','Legal effect and observation time separated.'),('provenance','Source-qualified institutional assertions.'),('ownership','Record steward does not own government power.'),('access','Disclosure policy and protected references.'),('retention','Custody and legal holds bound local retirement.'),('interoperability','Optional loss-aware vocabulary projections.')]
    coverage=dict(claim='Bounded public-institution memory draft, not universal administrative law or an independently reviewed legal engine.',confidence='medium',checklist=[dict(dimension=d,status='covered',notes=n) for d,n in dims]+[dict(dimension='validation',status='gap',notes='Research schema checked; nested schemas, legal-profile rules and negative runtime fixtures not implemented.'),dict(dimension='physical properties',status='not-applicable',notes='Institution is organizational; physical properties belong to referenced sites and assets.')],known_omissions=['Both providers timed out once; no independent external review.','Selected clauses only; full dated-pin/update/license and jurisdiction-profile verification pending.','No concrete institution-specific legal instrument or universal competence interpretation supplied.','No executable nested schemas, legal inference engine, succession/custody transfer or round-trip adapter.','Empty relation ledger; proposed composition has not been ratified.'],conflicts=[],regional_assumptions=['UK administrative/statistical/FOI examples are bounded and do not define all public institutions worldwide.'],adversarial_checks=['Public control classification does not negate institutional independence.','A distinct agency may lack separate legal personality.','Outsourcing does not alone change responsible authority.','A vacant post is distinct from a nonexistent institution.','A site is not a jurisdiction.','Reporting is not necessarily legal delegation.','Name change is not automatically succession.','Public scheme does not authorize every record disclosure.','Local edits cannot confer or abolish government powers.'])
    return dict(schema_version='1.0.0',model=model,sources=sources,structure=dict(bundles=bundles),functions=functions,composition=composition,service_layers=services,coverage=coverage)

if __name__=='__main__':
    (RUN/'codex.result.json').write_text(json.dumps(build(),ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
